// Poké Ball formula (Gen III/IV): a = (3·maxHP − 2·HP)·rate·ball·status / (3·maxHP), then four shake checks
function dgCatchChance(e,ball,penalty){const rate=DG_CATCH[(INDEX[e.species]||{}).tier||0]||45,status=(e.para||e.salt||e.cage>0||e.melt>0)?1.5:1;
 const a=Math.max(1,(3*e.maxhp-2*Math.max(1,e.hp))*rate*ball*status/(3*e.maxhp)*(penalty||1));if(a>=255)return 1;const b=1048560/Math.sqrt(Math.sqrt(16711680/a));return Math.pow(b/65536,4)}
