function dgMainShare(x,less){const me=mainSeconds(x.p),o=db.pokemon.filter(q=>q.id!==x.p.id);if(!o.length)return .5;return o.filter(q=>less?mainSeconds(q)<me:mainSeconds(q)>me).length/o.length}
